+	return "", i, false
+}
+
+func readEscape(src []byte, i int) (string, int, bool) {
+	if i+1 >= len(src) {
+		return "", i, false
+	}
+	switch src[i+1] {
+	case 'n':
+		return "\n", i + 2, true
+	case 'r':
+		return "\r", i + 2, true
+	case 't':
+		return "\t", i + 2, true
+	case '\\':
+		return "\\", i + 2, true
+	case '"':
+		return "\"", i + 2, true
+	case 'x':
+		if i+3 < len(src) {
+			if n, err := strconv.ParseUint(string(src[i+2:i+4]), 16, 8); err == nil {
+				return string([]byte{byte(n)}), i + 4, true
+			}
+		}
+	}
+	return string(src[i+1]), i + 2, true
+}
+
+// stringDef describes the raw literal associated with a $name in a rule.
+type stringDef struct {
+	name  string
+	gates []Gate
+}
+
+func parseStringDefs(ruleSource string) map[string]stringDef {
+	defs := make(map[string]stringDef)
+	lower := strings.ToLower(ruleSource)
+	stringsIdx := strings.Index(lower, "strings:")
+	if stringsIdx < 0 {
+		return defs
+	}
+	condIdx := strings.Index(lower[stringsIdx:], "condition:")
+	if condIdx < 0 {
+		return defs
+	}
+	section := ruleSource[stringsIdx+len("strings:") : stringsIdx+condIdx]
+
+	src := []byte(section)
+	for i := 0; i < len(src); {
+		i = skipSpaceAndComments(src, i)
+		if i >= len(src) || src[i] != '$' {
+			i++
+			continue
+		}
+		i++
+		nameStart := i
+		for i < len(src) && isIdentPart(src[i]) {
+			i++
+		}
+		name := string(src[nameStart:i])
+		i = skipSpaceAndComments(src, i)
+		if i >= len(src) || src[i] != '=' {
+			continue
+		}
+		i = skipSpaceAndComments(src, i+1)
+		if i >= len(src) {
+			break
+		}
+
+		var gates []Gate
+		switch src[i] {
+		case '"':
+			literal, after, ok := readQuoted(src, i)
+			if ok {
+				modsEnd := skipToLineEnd(src, after)
+				mods := strings.ToLower(string(src[after:modsEnd]))
+				gates = gatesForTextLiteral(literal, mods)
+				i = modsEnd
+			}
+		case '{':
+			hexSrc, after, ok := readBraceBlock(src, i)
+			if ok {
+				gates = gatesForHexLiteral(hexSrc)
+				i = after
+			}
+		case '/':
+			if after, ok := skipRegex(src, i); ok {
+				i = after
+			}
+		}
+		if name != "" {
+			defs[name] = stringDef{name: name, gates: gates}
+		}
+	}
