+		gate.MinEntropy = value
+	case "<":
+		gate.MaxEntropy = value - 1e-9
+	case "<=":
+		gate.MaxEntropy = value
+	case "==":
+		gate.MinEntropy = value
+		gate.MaxEntropy = value
+	default:
+		return Gate{}, false
+	}
+	return gate, true
