	profiles := make([]prefilter.ShardProfile, len(shards))
	for i, shard := range shards {
		profiles[i] = shard.Profile
	}
	set := &ShardSet{
		Shards:     shards,
		Profiles:   profiles,
		Classifier: prefilter.NewClassifier(profiles),
		RuleOrder:  ruleOrder,
		RuleCount:  len(profile.Rules),
	}
