func DoScanWithEngine(
	scanID string,
	hostMountPath string,
	ExtractorConfig cfg.Config,
	inactiveThreshold int,
	ScanMap *sync.Map,
	namespace,
	path, image, container string,
	engine *scan.Engine, writeToFile func(res output.IOCFound, scanID string)) {

	jobs.StartScanJob()
